function t(key){return d()[key]||key}
function save(){try{localStorage.setItem('oshimichi-favorites-v1',JSON.stringify(favorites))}catch(e){}}
function memberName(){if(selectedMembers.has('ALL'))return translations[language].all;const names=(memberData[selectedGroup]||[]).filter(m=>selectedMembers.has(m[0])).map(m=>language==='ja'?m[1]:m[2]);return names.join(' · ')||translations[language].all}
function showPage(page){currentPage=page;home.hidden=page!=='home';home.style.display=page==='home'?'':'none';benefits.hidden=page!=='home';benefits.style.display=page==='home'?'':'none';selection.classList.toggle('active',page==='selection');members.classList.toggle('active',page==='members');selection.setAttribute('aria-hidden',String(page!=='selection'));members.setAttribute('aria-hidden',String(page!=='members'));flowPages.forEach(id=>{const el=document.getElementById(id),active=id===page;el.classList.toggle('active',active);el.setAttribute('aria-hidden',String(!active))});window.scrollTo(0,0);if(page==='spots'){renderSpots();setTimeout(updateMap,50)}if(page==='favorites')renderFavorites();if(page==='course')renderCourseChoices()}
function renderMembers(){const dic=translations[language],grid=document.querySelector('#memberGrid');grid.replaceChildren();const items=[['ALL',dic.all,dic.allSub],...memberData[selectedGroup].map(x=>[x[0],language==='ja'?x[1]:x[2],x[0]])];items.forEach((x,i)=>{const b=document.createElement('button');b.className='member-card';b.type='button';b.setAttribute('aria-pressed',String(selectedMembers.has(x[0])));b.innerHTML='<span class="number">'+(i===0?'♡':String(i).padStart(2,'0'))+'</span><span class="decor">✳</span><span><strong></strong><small></small></span><span class="tick">'+(selectedMembers.has(x[0])?'✓':'＋')+'</span>';b.querySelector('strong').textContent=x[1];b.querySelector('small').textContent=x[2];
if(selectedGroup==='TWICE'||selectedGroup==='Stray Kids'){
 const imgSrc=(selectedGroup==='TWICE'?window.OSHI_TWICE_PHOTOS:window.OSHI_SKZ_PHOTOS)?.[x[0]];
 if(imgSrc){
   const photoBox=document.createElement('div');photoBox.className='member-photo oshi-embedded-photo';
   const img=document.createElement('img');img.src=imgSrc;img.alt=x[1]+' photo';img.loading='eager';img.decoding='async';if(x[0]==='ALL')img.style.objectFit='contain';
   photoBox.appendChild(img);
   const content=Array.from(b.children).find(el=>el.querySelector('strong'));
   b.insertBefore(photoBox,content||b.lastElementChild);
 }
}
if(selectedGroup==='IVE'||selectedGroup==='SEVENTEEN'){
 const photoBox=document.createElement('div');
 photoBox.className='member-photo oshi-embedded-photo';
 const src=(selectedGroup==='IVE'?window.OSHI_IVE_PHOTOS:window.OSHI_SEVENTEEN_PHOTOS)?.[x[0]];
 if(src){
  const img=document.createElement('img');
  img.src=src;img.alt=x[1];img.loading='eager';img.decoding='async';
  if(x[0]==='ALL')img.style.objectFit='contain';
  photoBox.appendChild(img);
 } else {
  photoBox.classList.add('oshi-photo-awaiting',selectedGroup==='IVE'?'ive-placeholder':'svt-placeholder');
  const icon=document.createElement('span');icon.className='photo-icon';icon.textContent='✳';
  const caption=document.createElement('span');caption.className='photo-caption';
  caption.textContent=language==='ja'?'写真は後日追加予定':'사진 추후 추가 예정';
  photoBox.append(icon,caption);
 }
 const content=Array.from(b.children).find(el=>el.querySelector('strong'));
 b.insertBefore(photoBox,content||b.lastElementChild);
}

b.addEventListener('click',()=>{const id=x[0];if(id==='ALL'){if(selectedMembers.has('ALL'))selectedMembers.clear();else{selectedMembers.clear();selectedMembers.add('ALL')}}else{selectedMembers.delete('ALL');if(selectedMembers.has(id))selectedMembers.delete(id);else selectedMembers.add(id)}selectedMember=selectedMembers.has('ALL')?'ALL':([...selectedMembers][0]||null);renderMembers()});grid.appendChild(b)});document.querySelector('#memberNext').disabled=selectedMembers.size===0;document.querySelector('#groupLabel').textContent=selectedGroup}
function translate(){const dic=translations[language];document.documentElement.lang=language;document.querySelector('#langSwitch').textContent=language==='ja'?'한국어 / KR':'日本語 / JP';const sels={'.nav-label':'nav','.eyebrow':'eyebrow','.description':'heroDesc','.hero h2':'heroTitle','.cta#start':'start','.tag-one':'tag1','.tag-two':'tag2','.benefit:nth-child(1) strong':'benefit1','.benefit:nth-child(1) p':'benefit1d','.benefit:nth-child(2) strong':'benefit2','.benefit:nth-child(2) p':'benefit2d','.benefit:nth-child(3) strong':'benefit3','.benefit:nth-child(3) p':'benefit3d','.selection h2':'step1Title','.selection .sub':'step1Desc','.twice .group-info small':'girl','.skz .group-info small':'boy','.selection-bottom p':'step1Foot','.footer':'footer'};Object.entries(sels).forEach(([sel,key])=>{const el=document.querySelector(sel);if(el){if(['heroTitle','heroDesc','step1Title','step1Desc'].includes(key))el.innerHTML=dic[key];else if(key==='start')el.firstChild.textContent=dic[key]+' ';else if(key==='tag1'||key==='tag2')el.lastChild.textContent=' '+dic[key];else if(key==='footer')el.innerHTML='<b>推し道 · OSHIMICHI</b><br>'+dic[key];else el.textContent=dic[key]}});document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=dic[el.dataset.i18n]);document.querySelectorAll('[data-i18n-html]').forEach(el=>el.innerHTML=dic[el.dataset.i18nHtml]);document.querySelectorAll('[data-x]').forEach(el=>{const val=d()[el.dataset.x];if(val!==undefined){if(['mapTitle','favTitle','courseTitle','mapFallback'].includes(el.dataset.x))el.innerHTML=val;else el.textContent=val}});document.querySelector('#spotSearch').placeholder=t('search');updateGeoUi();if(selectedGroup)renderMembers();if(currentPage==='spots')renderSpots();if(currentPage==='favorites')renderFavorites();if(currentPage==='course')renderCourseChoices();}
let userPosition=null,userMarker=null,nearbyRequested=false;
function haversine(a,b){const R=6371,toRad=Math.PI/180,dLat=(b.lat-a.lat)*toRad,dLng=(b.lng-a.lng)*toRad,h=Math.sin(dLat/2)**2+Math.cos(a.lat*toRad)*Math.cos(b.lat*toRad)*Math.sin(dLng/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(h)))}
function geoText(key){const ko=language==='ko';const texts={title:ko?'📍 내 주변 성지 찾기':'📍 現在地から探す',button:ko?'◎ 내 위치 확인':'◎ 現在地を取得',idle:ko?'위치를 허용하면 가까운 장소부터 보여드려요.':'位置情報を許可すると近いスポットから表示します。',loading:ko?'현재 위치를 확인하는 중이에요…':'現在地を取得しています…',ready:ko?'현재 위치 기준 가까운 순서로 정렬했어요. 거리는 직선거리예요.':'現在地から近い順に表示中。距離は直線距離です。',far:ko?'현재 위치가 서울과 멀어 서울 성지가 멀게 표시될 수 있어요.':'現在地がソウルから遠いため、スポットまでの距離が長く表示されます。',denied:ko?'위치 권한이 거부됐어요. 브라우저 설정에서 허용하거나 전체 장소를 볼 수 있어요.':'位置情報が許可されませんでした。ブラウザの設定を変更するか、全スポットをご覧ください。',unavailable:ko?'현재 위치를 가져올 수 없어요. 전체 장소는 계속 볼 수 있어요.':'現在地を取得できません。スポット一覧は引き続き利用できます。',https:ko?'현재 위치 기능은 HTTPS 사이트 또는 localhost에서만 사용할 수 있어요.':'位置情報の取得にはHTTPSまたはlocalhostが必要です。'};return texts[key]}
function updateGeoUi(status){document.getElementById('geoTitle').textContent=geoText('title');document.getElementById('findNearby').textContent=geoText('button');document.getElementById('geoStatus').textContent=status|| (userPosition?geoText('ready'):geoText('idle'))}
function requestLocation(){nearbyRequested=true;if(!window.isSecureContext){updateGeoUi(geoText('https'));return}if(!navigator.geolocation){updateGeoUi(geoText('unavailable'));return}updateGeoUi(geoText('loading'));navigator.geolocation.getCurrentPosition(pos=>{userPosition={lat:pos.coords.latitude,lng:pos.coords.longitude};const isFar=haversine(userPosition,{lat:37.5665,lng:126.978})>80;updateGeoUi(geoText(isFar?'far':'ready'));if(currentPage==='spots')renderSpots()},err=>{updateGeoUi(geoText(err.code===1?'denied':'unavailable'));},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
function filteredPlaces(){const term=document.getElementById('spotSearch').value.trim().toLowerCase();const places=demoPlaces.filter(p=>p.group===selectedGroup&&(selectedMembers.has('ALL')||(p.group==='TWICE'?(Array.isArray(p.members)&&p.members.some(m=>selectedMembers.has(m))):(p.member==='ALL'||selectedMembers.has(p.member))))).filter(p=>!term||[p.ja,p.ko,p.areaJa,p.areaKo,p.address,p.member].some(x=>String(x).toLowerCase().includes(term)));return userPosition?places.sort((a,b)=>(Number.isFinite(a.lat)&&Number.isFinite(a.lng)?haversine(userPosition,a):Infinity)-(Number.isFinite(b.lat)&&Number.isFinite(b.lng)?haversine(userPosition,b):Infinity)):places}
function placeName(p){return language==='ja'?p.ja:p.ko}
function placeNote(p){return language==='ja'?p.descriptionJa:p.descriptionKo}
function renderSpots(){document.getElementById('spotIdentity').textContent='♡ '+selectedGroup+' · '+memberName();if(!nearbyRequested)updateGeoUi();const places=filteredPlaces(),list=document.getElementById('spotList');document.getElementById('spotCount').textContent=places.length+' '+t('count');list.replaceChildren();places.forEach(p=>{const card=document.createElement('article');card.className='spot-card';const isSaved=favorites.includes(p.id);card.innerHTML='<div class="spot-kicker"><span class="spot-area"></span><span class="spot-distance"></span></div><h3 class="spot-title"></h3><div class="spot-meta"></div><div class="spot-address"></div><a class="source-link" target="_blank" rel="noopener noreferrer"></a><div class="spot-actions"><button class="pink-button save-spot"></button><button class="soft-button locate-spot"></button></div>';card.querySelector('.spot-area').textContent=(language==='ja'?p.areaJa:p.areaKo)+' · '+p.group;card.querySelector('.spot-distance').textContent=userPosition?(Number.isFinite(p.lat)&&Number.isFinite(p.lng)?'📍 '+haversine(userPosition,p).toFixed(1)+' km':(language==='ja'?'位置未確認':'위치 미확인')):'';card.querySelector('.spot-distance').className='distance-pill';card.querySelector('.spot-title').textContent=placeName(p);card.querySelector('.spot-meta').textContent=placeNote(p);card.querySelector('.spot-address').textContent='⌁ '+p.address;const source=card.querySelector('.source-link');source.textContent=language==='ja'?'↗ 関連情報・出典を見る':'↗ 관련 정보 · 출처 보기';if(p.source){source.href=p.source;}else{source.removeAttribute('href');source.setAttribute('aria-disabled','true');source.textContent=language==='ja'?'出典の確認が必要':'출처 확인 필요';}card.querySelector('.save-spot').textContent=isSaved?t('saved'):t('favorite');card.querySelector('.save-spot').onclick=()=>{if(!favorites.includes(p.id))favorites.push(p.id);save();showPage('favorites')};card.querySelector('.locate-spot').textContent=t('go');card.querySelector('.locate-spot').onclick=()=>{if(map){map.setView([p.lat,p.lng],14);const m=markers.find(m=>m.placeId===p.id);m?.openPopup();document.getElementById('mapBox').scrollIntoView({behavior:'smooth',block:'center'})}else document.getElementById('mapBox').scrollIntoView({behavior:'smooth',block:'center'})};list.appendChild(card)});updateMap(places)}
function initMap(){if(map||!window.L)return;try{map=L.map('spotMap',{scrollWheelZoom:false}).setView([37.552,126.99],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors',maxZoom:19}).addTo(map)}catch(e){document.getElementById('mapBox').classList.add('no-map')}}
function updateMap(places){if(!map)initMap();if(!map){document.getElementById('mapBox').classList.add('no-map');return}map.invalidateSize();markers.forEach(m=>map.removeLayer(m));markers=[];if(userMarker){map.removeLayer(userMarker);userMarker=null}const shown=places||filteredPlaces();shown.filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lng)).forEach(p=>{const m=L.marker([p.lat,p.lng]).addTo(map);m.placeId=p.id;const popup=document.createElement('div');const title=document.createElement('strong');title.textContent=placeName(p);const info=document.createElement('p');info.textContent=placeNote(p);const btn=document.createElement('button');btn.className='pink-button';btn.textContent=t('favorite');btn.onclick=()=>{if(!favorites.includes(p.id))favorites.push(p.id);save();showPage('favorites')};popup.append(title,info,btn);m.bindPopup(popup);markers.push(m)});if(userPosition){userMarker=L.circleMarker([userPosition.lat,userPosition.lng],{radius:9,color:'#fff',weight:3,fillColor:'#bb577d',fillOpacity:1}).addTo(map);userMarker.bindPopup(language==='ja'?'📍 現在地':'📍 내 위치');const closest=shown.filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lng)).slice(0,3);const points=[userPosition,...closest].map(x=>[x.lat,x.lng]);if(points.length>1&&closest[0]&&haversine(userPosition,closest[0])<80)map.fitBounds(L.latLngBounds(points).pad(.35));else map.setView([userPosition.lat,userPosition.lng],11)}else{const ms=markers.map(m=>m.getLatLng());if(ms.length>1)map.fitBounds(L.latLngBounds(ms).pad(.25));else if(ms.length===1)map.setView(ms[0],13);else map.setView([37.552,126.99],11)}}
function renderFavorites(){const list=document.getElementById('favoriteList');list.replaceChildren();if(!favorites.length){const empty=document.createElement('div');empty.className='flow-empty';empty.innerHTML='<strong></strong><span></span>';empty.querySelector('strong').textContent=t('empty');empty.querySelector('span').textContent=t('empty2');list.appendChild(empty)}favorites.forEach(id=>{const p=demoPlaces.find(x=>x.id===id);if(!p)return;const item=document.createElement('article');item.className='fav-item';const main=document.createElement('div');main.className='fav-main';const name=document.createElement('span');name.className='fav-name';name.textContent='♥ '+placeName(p);const meta=document.createElement('span');meta.className='fav-detail';meta.textContent=p.group+' · '+p.address;main.append(name,meta);const remove=document.createElement('button');remove.className='soft-button';remove.textContent=t('remove');remove.onclick=()=>{favorites=favorites.filter(x=>x!==id);courseChosen.delete(id);save();renderFavorites()};item.append(main,remove);list.appendChild(item)});document.getElementById('toCourse').disabled=!favorites.length}
function renderCourseChoices(){const list=document.getElementById('courseSelectList');list.replaceChildren();if(!favorites.length){const empty=document.createElement('div');empty.className='flow-empty';empty.textContent=t('empty');list.appendChild(empty)}favorites.forEach(id=>{const p=demoPlaces.find(x=>x.id===id);if(!p)return;const item=document.createElement('label');item.className='fav-item';const main=document.createElement('div');main.className='fav-main';const name=document.createElement('span');name.className='fav-name';name.textContent=placeName(p);const meta=document.createElement('span');meta.className='fav-detail';meta.textContent=p.group+' · '+p.address;main.append(name,meta);const control=document.createElement('div');control.className='fav-controls';const text=document.createElement('span');text.className='fav-detail';text.textContent=t('select');const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.className='choose-box';checkbox.checked=courseChosen.has(id)||(!courseChosen.size&&favorites.includes(id));if(checkbox.checked)courseChosen.add(id);checkbox.onchange=()=>{checkbox.checked?courseChosen.add(id):courseChosen.delete(id);document.getElementById('courseResult').replaceChildren()};control.append(text,checkbox);item.append(main,control);list.appendChild(item)});document.getElementById('createCourse').disabled=!favorites.length;document.getElementById('courseResult').replaceChildren()}
function distance(a,b){const lat=(a.lat+b.lat)/2*Math.PI/180,dx=(a.lng-b.lng)*Math.cos(lat),dy=a.lat-b.lat;return dx*dx+dy*dy}
function routeOrder(places){if(places.length<3)return places;const remain=places.slice(1),order=[places[0]];while(remain.length){let best=0;for(let i=1;i<remain.length;i++)if(distance(order.at(-1),remain[i])<distance(order.at(-1),remain[best]))best=i;order.push(remain.splice(best,1)[0])}return order}
function makeCourse(){const chosen=demoPlaces.filter(p=>courseChosen.has(p.id)&&favorites.includes(p.id));const result=document.getElementById('courseResult');result.replaceChildren();if(!chosen.length){result.textContent=t('needSelect');return}const ordered=routeOrder(chosen);const header=document.createElement('h3');header.style.color='#76525e';header.textContent=t('suggested')+' · '+ordered.length+' '+t('included');result.appendChild(header);const list=document.createElement('div');list.className='course-list';ordered.forEach((p,i)=>{const item=document.createElement('article');item.className='course-item';const number=document.createElement('span');number.className='course-number';number.textContent=String(i+1).padStart(2,'0');const main=document.createElement('div');main.className='course-main';const title=document.createElement('span');title.className='course-name';title.textContent=placeName(p);const desc=document.createElement('span');desc.className='course-detail';desc.textContent=p.address;main.append(title,desc);item.append(number,main);list.appendChild(item)});result.appendChild(list);const mapEl=document.createElement('div');mapEl.className='course-route-map';mapEl.id='courseRouteMap';result.appendChild(mapEl);if(!window.L){mapEl.className='route-fallback';mapEl.textContent=ordered.map((p,i)=>(i+1)+'. '+placeName(p)).join(' → ');return}setTimeout(()=>{try{if(routeMap){routeMap.remove();routeMap=null}routeMap=L.map(mapEl,{scrollWheelZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors',maxZoom:19}).addTo(routeMap);const points=ordered.map(p=>[p.lat,p.lng]);ordered.forEach((p,i)=>L.marker([p.lat,p.lng]).addTo(routeMap).bindPopup((i+1)+'. '+placeName(p)));if(points.length>1){L.polyline(points,{color:'#bf748e',weight:4,dashArray:'7 8'}).addTo(routeMap);routeMap.fitBounds(L.latLngBounds(points).pad(.24))}else routeMap.setView(points[0],13);routeMap.invalidateSize()}catch(e){mapEl.textContent=t('mapFallback').replace(/<[^>]*>/g,' ')}} ,75)}
document.querySelector('#logoHome').addEventListener('click',()=>showPage('home'));document.querySelector('#findNearby').addEventListener('click',requestLocation);document.querySelector('#langSwitch').addEventListener('click',()=>{language=language==='ja'?'ko':'ja';translate()});document.querySelector('#start').addEventListener('click',()=>showPage('selection'));document.querySelector('#back').addEventListener('click',()=>showPage('home'));document.querySelector('#memberBack').addEventListener('click',()=>showPage('selection'));document.querySelectorAll('.group').forEach(btn=>btn.addEventListener('click',()=>{selectedGroup=btn.dataset.name;selectedMember=null;selectedMembers.clear();renderMembers();showPage('members')}));document.querySelector('#memberNext').addEventListener('click',()=>{if(selectedMembers.size)showPage('spots')});document.querySelectorAll('[data-go]').forEach(btn=>btn.addEventListener('click',()=>showPage(btn.dataset.go)));document.querySelector('#spotSearch').addEventListener('input',renderSpots);document.querySelector('#toCourse').addEventListener('click',()=>showPage('course'));document.querySelector('#createCourse').addEventListener('click',makeCourse);translate();
